//#region src/connect/handler.ts
function wrapConnectHandler(handler) {
	return async (input) => {
		const apiKey = input.context.config.authorization;
		delete input.context.config.authorization;
		return await handler(input, new TerrosApiClient({ apiKey: apiKey?.replace(/^ApiKey /, "") }));
	};
}
